const empresa   = $('📊 Obtener Perfil Empresa').item.json.records[0]?.fields || {};
const wpPosts   = $('🔎 Detectar Builder WP').item.json;
const wpPages   = $('🔗 Obtener Páginas WP').item.json;

// ── Keyword ingresada por el usuario ──────────────────────────
let keywordPrincipal = 'hostel en managua';
try {
  keywordPrincipal = $('✏️ KEYWORD (editar aquí)').item.json.keyword || keywordPrincipal;
} catch(e) {
  // Nodo no ejecutado aún (solo pasa al probar pasos individuales)
}

// ── Detectar Builder ──────────────────────────────────────────
let builderType = 'classic';
const wpArr = Array.isArray(wpPosts) ? wpPosts : [];
const sampleContent = wpArr[0]?.content?.raw || wpArr[0]?.content?.rendered || '';
if      (sampleContent.includes('[et_pb_'))             builderType = 'divi';
else if (sampleContent.includes('<!-- wp:'))            builderType = 'gutenberg';
else if (sampleContent.includes('elementor-section'))   builderType = 'elementor';

// ── Páginas WP para links internos ────────────────────────────
let paginasWP = [];
try {
  const pages = Array.isArray(wpPages) ? wpPages : [];
  paginasWP = pages
    .filter(p => p.link && p.title?.rendered)
    .map(p => ({ titulo: p.title.rendered, url: p.link, slug: p.slug }));
} catch(e) {}

const instrucciones_ia = empresa['Instrucciones_IA'] || '';

return [{
  json: {
    empresa_nombre:          empresa['\uFEFFnombre_empresa'] || empresa['nombre_empresa'] || 'Orison Hostels',
    empresa_descripcion:     empresa['descripción_corta'] || '',
    empresa_propuesta_valor: empresa['propuesta_valor'] || '',
    empresa_ciudad:          empresa['ciudad base'] || '',
    empresa_web:             empresa['sitio_web'] || 'orisonhostels.com',
    instrucciones_ia,
    keywordPrincipal,
    builderType,
    paginasWP
  }
}];

const raw = $input.item.json.choices?.[0]?.message?.content
  || $input.item.json.candidates?.[0]?.content?.parts?.[0]?.text
  || '{}';

let art;
try { art = JSON.parse(raw); }
catch(e) {
  const match = raw.match(/\{[\s\S]*\}/);
  art = match ? JSON.parse(match[0]) : {};
}

const ctx = $('🔧 Preparar Contexto').item.json;

return [{
  json: {
    ...ctx,
    titulo_h1:         art.titulo_h1 || art.titulo || art.title || 'Untitled',
    slug:              art.slug || 'new-post',
    meta_descripcion:  art.meta_descripcion || art.meta_description || '',
    keyword_principal: art.keyword_principal || ctx.keywordPrincipal,
    tiempo_lectura:    art.tiempo_lectura || art.reading_time || 4,
    intro:             art.intro || '',
    secciones:         art.secciones || art.sections || [],
    faq:               art.faq || [],
    cta_texto:         art.cta_texto || art.cta || ''
  }
}];

const { secciones, faq, intro, titulo_h1, cta_texto, builderType, empresa_web } = $input.item.json;

let imgCounter = 0;

// ─── FAQ Schema.org HTML ──────────────────────────────────────
function buildFaqHtml(faqItems) {
  if (!faqItems || faqItems.length === 0) return '';
  const items = faqItems.map(f => `
  <div itemscope itemprop="mainEntity" itemtype="https://schema.org/Question">
    <h3 itemprop="name">${f.pregunta}</h3>
    <div itemscope itemprop="acceptedAnswer" itemtype="https://schema.org/Answer">
      <p itemprop="text">${f.respuesta}</p>
    </div>
  </div>`).join('\n');
  return `\n<h2>Frequently Asked Questions</h2>\n<div itemscope itemtype="https://schema.org/FAQPage">\n${items}\n</div>`;
}

// ─── CTA HTML ─────────────────────────────────────────────────
function buildCtaHtml(texto) {
  const t = texto || `Ready to protect your shipment with custom wood crating in Miami?`;
  return `<p><strong>${t}</strong></p>\n<p><a href="https://${empresa_web}/request-a-quote/">Request a Free Quote →</a></p>`;
}

// ─── Construir sección individual ─────────────────────────────
function buildSection(s, tag) {
  // tag = 'html' | 'divi' | 'gutenberg'
  if (s.tipo === 'h2') {
    if (tag === 'gutenberg') return `<!-- wp:heading {"level":2} -->\n<h2>${s.texto}</h2>\n<!-- /wp:heading -->`;
    return `<h2>${s.texto}</h2>`;
  }
  if (s.tipo === 'h3') {
    if (tag === 'gutenberg') return `<!-- wp:heading {"level":3} -->\n<h3>${s.texto}</h3>\n<!-- /wp:heading -->`;
    return `<h3>${s.texto}</h3>`;
  }
  if (s.tipo === 'parrafo') {
    if (tag === 'gutenberg') return `<!-- wp:paragraph -->\n<p>${s.texto}</p>\n<!-- /wp:paragraph -->`;
    return `<p>${s.texto}</p>`;
  }
  if (s.tipo === 'lista') {
    const items = (s.items||[]).map(i=>`<li>${i}</li>`).join('\n');
    const html = `<ul>\n${items}\n</ul>`;
    if (tag === 'gutenberg') return `<!-- wp:list -->\n${html}\n<!-- /wp:list -->`;
    return html;
  }
  if (s.tipo === 'imagen') {
    imgCounter++;
    const alt = s.alt_sugerido || `Wood crating Miami - image ${imgCounter}`;
    const desc = s.descripcion_imagen ? `<!-- Imagen ${imgCounter}: ${s.descripcion_imagen} -->` : '';
    if (tag === 'gutenberg') {
      return `<!-- wp:image -->\n<figure class="wp-block-image">${desc}\n<img src="##IMAGEN_${imgCounter}##" alt="${alt}"/>\n</figure>\n<!-- /wp:image -->`;
    }
    return `${desc}\n<img src="##IMAGEN_${imgCounter}##" alt="${alt}" style="max-width:100%;height:auto;" />`;
  }
  if (s.tipo === 'cta') {
    const html = buildCtaHtml(s.texto);
    if (tag === 'gutenberg') return `<!-- wp:paragraph -->\n${html}\n<!-- /wp:paragraph -->`;
    return html;
  }
  if (s.tipo === 'link_interno') {
    const html = `<p><a href="${s.url || '#'}">${s.anchor || s.texto}</a></p>`;
    if (tag === 'gutenberg') return `<!-- wp:paragraph -->\n${html}\n<!-- /wp:paragraph -->`;
    return html;
  }
  return '';
}

// ─── DIVI ─────────────────────────────────────────────────────
function buildDivi() {
  let textBuffer = `<p>${intro}</p>\n`;
  let blocks = [];

  function flushText() {
    if (textBuffer.trim()) {
      blocks.push(`[et_pb_text _builder_version="4.0"]${textBuffer}[/et_pb_text]`);
      textBuffer = '';
    }
  }

  for (const s of secciones) {
    if (s.tipo === 'imagen') {
      flushText();
      imgCounter++;
      const alt = s.alt_sugerido || `Wood crating Miami - ${imgCounter}`;
      const desc = s.descripcion_imagen ? `\n<!-- Imagen ${imgCounter}: ${s.descripcion_imagen} -->` : '';
      blocks.push(`[et_pb_image src="##IMAGEN_${imgCounter}##" alt="${alt}" _builder_version="4.0"][/et_pb_image]${desc}`);
    } else {
      textBuffer += buildSection(s, 'html') + '\n';
    }
  }

  // FAQ
  textBuffer += buildFaqHtml(faq) + '\n';
  // CTA final
  textBuffer += buildCtaHtml(cta_texto) + '\n';
  flushText();

  return (
    `[et_pb_section fb_built="1" _builder_version="4.0"]\n`+
    `[et_pb_row _builder_version="4.0"]\n`+
    `[et_pb_column type="4_4" _builder_version="4.0"]\n\n`+
    blocks.join('\n\n')+
    `\n\n[/et_pb_column]\n[/et_pb_row]\n[/et_pb_section]`
  );
}

// ─── GUTENBERG ────────────────────────────────────────────────
function buildGutenberg() {
  const parts = [];
  parts.push(`<!-- wp:paragraph -->\n<p>${intro}</p>\n<!-- /wp:paragraph -->`);
  for (const s of secciones) {
    const block = buildSection(s, 'gutenberg');
    if (block) parts.push(block);
  }
  // FAQ
  if (faq && faq.length > 0) {
    parts.push(`<!-- wp:heading {"level":2} -->\n<h2>Frequently Asked Questions</h2>\n<!-- /wp:heading -->`);
    for (const f of faq) {
      parts.push(
        `<!-- wp:heading {"level":3} -->\n<h3 itemprop="name">${f.pregunta}</h3>\n<!-- /wp:heading -->\n`+
        `<!-- wp:paragraph -->\n<p itemprop="text">${f.respuesta}</p>\n<!-- /wp:paragraph -->`
      );
    }
  }
  // CTA
  parts.push(
    `<!-- wp:paragraph -->\n<p><strong>${cta_texto || 'Get your free quote today!'}</strong></p>\n<!-- /wp:paragraph -->\n`+
    `<!-- wp:buttons -->\n<div class="wp-block-buttons"><div class="wp-block-button">`+
    `<a class="wp-block-button__link" href="https://${empresa_web}/request-a-quote/">Request a Free Quote</a>`+
    `</div></div>\n<!-- /wp:buttons -->`
  );
  return parts.join('\n\n');
}

// ─── CLASSIC / HTML ───────────────────────────────────────────
function buildClassic() {
  let html = `<p>${intro}</p>\n`;
  for (const s of secciones) {
    html += buildSection(s, 'html') + '\n';
  }
  html += buildFaqHtml(faq) + '\n';
  html += buildCtaHtml(cta_texto) + '\n';
  return html;
}

let wpContent = '';
if      (builderType === 'divi')       wpContent = buildDivi();
else if (builderType === 'gutenberg')  wpContent = buildGutenberg();
else                                   wpContent = buildClassic();

return [{
  json: {
    ...$input.item.json,
    wpContent,
    imgCount: imgCounter
  }
}];
